import html
import json
from pathlib import Path
import statistics

ROOT=Path(__file__).resolve().parent
rows=json.loads((ROOT/'results.json').read_text(encoding='utf-8'))
summary=json.loads((ROOT/'summary.json').read_text(encoding='utf-8'))
esc=html.escape
A,B=summary['A'],summary['B']
delta=summary['change_pct']
direction='慢' if delta>0 else '快'
jev_rows=[r for r in rows if r['arm']=='B']
jev_median=statistics.median(r['typesafe']['api_s'] for r in jev_rows)
max_time=max(r['total_s'] for r in rows)
table=''.join(f'''<tr><td>{r['pair']}</td><td>{'A · 直接生成' if r['arm']=='A' else 'B · Jev 筛选后生成'}</td><td>{(r['typesafe']['api_s'] if r['typesafe'] else 0):.2f}</td><td>{r['elapsed_s']:.2f}</td><td><b>{r['total_s']:.2f}</b></td><td>{r['input_characters']}</td><td>{r['characters']} / {r['han_characters']}</td><td>{sum(r['checks'].values())}/{len(r['checks'])}</td></tr>''' for r in rows)
charts=''.join(f'''<div class="bar-row"><span>{r['arm']}{r['pair']}</span><div class="bar-track"><div class="bar {'b' if r['arm']=='B' else ''}" style="width:{r['total_s']/max_time*100:.2f}%"></div></div><strong>{r['total_s']:.2f}s</strong></div>''' for r in sorted(rows,key=lambda r:(r['pair'],r['arm'])))
outputs=''.join(f'''<details><summary>{r['arm']}{r['pair']} · {r['total_s']:.2f} 秒 · {r['characters']} 字符 · 展开实际生成内容</summary><pre>{esc(r['text'])}</pre><p class="small">返回用量：{esc(json.dumps(r['usage'],ensure_ascii=False))}</p></details>''' for r in rows)
issues=[(r['arm']+str(r['pair']),r.get('item_errors',[]),r.get('tools_used',[])) for r in rows if any('Skill descriptions were shortened' not in x for x in r.get('item_errors',[])) or r.get('tools_used')]
issue_note='检测到运行时错误或工具事件，详见原始记录；总时长可能包含额外等待，不应解释为纯模型速度。' if issues else '正式运行未记录额外工具调用或网络回退错误；两组均出现技能描述缩短的元数据提示。CLI 固定上下文仍占较多输入 token，详见每次 usage。'
scope_scores=''.join(f'''<tr><td>B{r['pair']}</td><td>{r['passage_count']} / 16</td><td>{esc(', '.join(r['typesafe']['retained_ids']))}</td></tr>''' for r in jev_rows)
content=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TypeSafe 实际调用速度对比</title><style>
:root{{--bg:#f4f3ed;--ink:#243831;--muted:#62736b;--green:#22634d;--orange:#bd653c;--line:#d8ddd4}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.8 'Segoe UI','Microsoft YaHei',sans-serif}}main{{max-width:1150px;margin:auto;padding:42px 30px}}h1{{font-size:42px;line-height:1.3;margin:14px 0}}h2{{font-size:24px;margin:0 0 16px}}h3{{margin:0;font-size:18px}}p{{margin:8px 0 18px}}a{{color:var(--green)}}.eyebrow{{font:12px Consolas,monospace;letter-spacing:2px;color:var(--green)}}.small{{font-size:13px;color:var(--muted);overflow-wrap:anywhere}}.lead{{font-size:19px;max-width:900px}}.metrics{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:28px 0}}.metric,.panel{{border:1px solid var(--line);background:#fffef9;border-radius:12px;padding:24px}}.metric b{{font-size:36px;display:block;line-height:1.6}}.metric span{{font-size:13px;color:var(--muted)}}.notice{{border-left:4px solid var(--orange);padding:14px 20px;background:#ece9df;border-radius:0 9px 9px 0}}section{{margin:36px 0}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}.flow{{text-align:center;padding:18px;background:#edf0e6;border-radius:8px;margin-top:15px}}.flow b{{display:block}}.flow span{{color:var(--orange)}}.bar-row{{display:flex;align-items:center;gap:12px;margin:12px 0;font:14px Consolas,monospace}}.bar-row>span{{width:25px}}.bar-track{{flex:1;background:#eceee5;border-radius:4px;overflow:hidden}}.bar{{height:22px;background:var(--green)}}.bar.b{{background:var(--orange)}}.bar-row strong{{width:85px}}.scroll{{overflow:auto}}table{{width:100%;border-collapse:collapse;font-size:13px}}th,td{{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}}th{{background:#edf0e7}}th{{white-space:nowrap}}pre{{background:#243831;color:#edf0e5;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:8px;padding:20px;font:14px/1.9 Consolas,'Microsoft YaHei',monospace}}details{{border-bottom:1px solid var(--line);padding:17px 0}}summary{{cursor:pointer;font-size:14px;font-weight:600}}li{{margin:8px 0}}footer{{font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:22px}}@media(max-width:700px){{main{{padding:25px 18px}}h1{{font-size:31px}}.metrics,.two{{grid-template-columns:1fr}}.metric b{{font-size:30px}}.panel{{padding:18px}}}}
</style></head><body><main><div class="eyebrow">MEASURED · 3 PAIRED RUNS · NO FABRICATED DATA</div><h1>调用 TypeSafe，生成文档会更快吗？</h1><p class="lead">本次小样本中，加入 Jev 筛选后的总耗时中位数比直接生成<strong>{direction} {abs(delta):.1f}%</strong>。这是一条具体流程的实测结果，不能推广为所有模型、所有文档的固定收益。</p><p class="small">测试时间：{esc(summary['timestamp'])} · 写作模型：{esc(summary['writer_requested'])} / medium · Jev 实际返回：{esc(jev_rows[0]['typesafe']['model'])}</p>
<div class="metrics"><div class="metric"><span>A / 不调用 TypeSafe</span><b>{A['median_s']:.2f}s</b><span>总耗时中位数 · {A['n']} 次</span></div><div class="metric"><span>B / Jev 筛选 + 同一写作模型</span><b>{B['median_s']:.2f}s</b><span>总耗时中位数 · {B['n']} 次</span></div><div class="metric"><span>Jev 筛选阶段</span><b>{jev_median:.2f}s</b><span>API 请求耗时中位数 · 已计入 B</span></div></div>
<div class="notice"><strong>确实调用了 API：</strong>Key 来自本机 Windows 用户环境，未写入代码或报告。Jev 输出的是资料相关性判断；最终介绍文字由相同的 Codex 模型生成。它不是一个能通过加 Key 直接加速长文输出的开关。<a href="https://docs.typesafe.ai/api">API 文档</a> · <a href="https://docs.typesafe.ai/concepts/system-one">模型能力说明</a></div>
<section><h2>比较的两条流程</h2><div class="two"><div class="panel"><h3>A · 直接生成</h3><div class="flow"><b>16 段固定 Ponytail 材料</b><span>↓</span><b>Codex 生成简短上手说明</b></div><p class="small">没有 TypeSafe 调用；由写作模型自行忽略无关资料。</p></div><div class="panel"><h3>B · 增加 TypeSafe 筛选</h3><div class="flow"><b>相同 16 段材料</b><span>↓</span><b>Jev 一次判断 16 段相关性</b><span>↓</span><b>同一 Codex 生成上手说明</b></div><p class="small">筛选阈值为演示参数 0.7；6 段必需信息由代码强制保留，避免筛掉明确要求。</p></div></div></section>
<section class="panel"><h2>逐轮总耗时</h2><p class="small">绿色 A：直接生成；橙色 B：含 Jev 筛选。顺序为 A1 → B1 → B2 → A2 → A3 → B3。</p>{charts}</section>
<section><h2>原始测量值</h2><div class="panel scroll"><table><thead><tr><th>轮次</th><th>流程</th><th>Jev / 秒</th><th>写作调用 / 秒</th><th>总耗时 / 秒</th><th>输入字符</th><th>输出字符 / 汉字</th><th>要点检查</th></tr></thead><tbody>{table}</tbody></table></div><p class="small">总耗时包括网络、筛选、Codex CLI 进程与请求的等待；不是纯模型解码时间。输出字符含 Markdown 和命令。“要点检查”是预定义字符串检查，不代表全文语义质量已被自动证明。</p></section>
<section class="panel"><h2>对比条件与局限</h2><ul><li>两组使用同一任务、固定材料、同一写作模型与 medium 推理档位。要求恰好四步、约 300–450 个汉字，准确保留安装与激活要点。</li><li>每次独立执行，交替顺序减少固定先后偏差。本次 CLI 禁用插件、关闭用户配置加载和联网搜索，并通过临时 provider 参数固定 HTTPS；不改变用户配置文件。</li><li>两端先做了单独连通性测试，不计入三轮成绩。没有主动启用客户端响应缓存；服务端缓存、排队、网络和后台负载无法完全控制，返回的 token 信息保留在原始 JSON。</li><li>B 改变的是输入资料的筛选流程，不能据此声称“TypeSafe 提升了同一模型的逐 token 生成速度”。最终输出长度与内容差异也会影响结果。</li><li>样本仅三对、主题仅 Ponytail 简短指南；没有完整重跑此前含搜索、设计、HTML 编写与浏览器验证的任务。</li><li>{issue_note}</li><li>未估算费用：返回 token 用量已保留，但不同服务的实际账户费率与 Codex 订阅计量不能直接相加比较。</li></ul></section>
<section><h2>Jev 实际保留了哪些资料？</h2><div class="panel scroll"><table><thead><tr><th>运行</th><th>保留段数</th><th>资料标识</th></tr></thead><tbody>{scope_scores}</tbody></table></div><p class="small">每段的 noul 值与用量保存在 results.json；这些值是模型的相关性判断，不是内容正确率。</p></section>
<section class="panel"><h2>展开查看真正生成的六份文字</h2>{outputs}</section>
<section><h2>复现与数据</h2><p><a href="benchmark.py">测试脚本</a> · <a href="results.json">逐次结果 JSON</a> · <a href="summary.json">统计摘要</a> · <a href="report.py">报告生成脚本</a></p><pre>python benchmark.py
python report.py</pre><p class="small">需本机 Codex 已登录且模型可用，以及配置 TYPESAFE_API_KEY。脚本优先读取进程环境，Windows 下缺省读取用户环境；不会在文件里保存 Key。再次执行会覆盖本目录的同名测量结果。</p></section>
<footer>首次 Jev 连通性探测：1.70 秒，返回 jev-1.13.0。原有第三方写作网关返回 HTTP 503，未计入比较；最初 Codex 的 WebSocket 超时回退记录保存在 <a href="excluded-transport-runs.json">排除记录</a>，固定 HTTPS 后重新测试。官方方法参考：<a href="https://docs.typesafe.ai/cookbooks/rerank_typesafe">资料重排 cookbook</a>。</footer></main></body></html>'''
(ROOT/'comparison.html').write_text(content,encoding='utf-8')
print(json.dumps({'report':str(ROOT/'comparison.html'),'A_median_s':A['median_s'],'B_median_s':B['median_s'],'B_change_pct':delta,'issues':len(issues)},ensure_ascii=False))
